    <!-- Scripts JavaScript -->
    <script data-cfasync="false" src="/cdn-cgi/scripts/5c5dd728/cloudflare-static/email-decode.min.js"></script>
    
    <script>
        // ============================================
        // GESTION DES FORMATIONS DYNAMIQUE
        // ============================================
        
        document.addEventListener('DOMContentLoaded', function() {
            // Navigation entre formations
            const navButtons = document.querySelectorAll('.formation-nav-btn');
            const sections = document.querySelectorAll('.formation-section');
            
            // Par défaut, on affiche seulement les formations Stage
            sections.forEach(section => {
                if (section.id !== 'stage') {
                    section.classList.remove('active');
                }
            });
            
            navButtons.forEach(button => {
                button.addEventListener('click', function() {
                    const target = this.getAttribute('data-target');
                    
                    // Mettre à jour les boutons actifs
                    navButtons.forEach(btn => btn.classList.remove('active'));
                    this.classList.add('active');
                    
                    // Afficher la section correspondante
                    sections.forEach(section => {
                        section.classList.remove('active');
                        if (section.id === target) {
                            section.classList.add('active');
                        }
                    });
                    
                    // Faire défiler vers la section
                    if (target !== 'all') {
                        document.getElementById(target).scrollIntoView({ behavior: 'smooth' });
                    }
                });
            });
            
            // Gestion du scroll vers les formations
            document.getElementById('scrollToFormations').addEventListener('click', function(e) {
                e.preventDefault();
                document.getElementById('formationNav').scrollIntoView({ behavior: 'smooth' });
            });

            // Appliquer la section depuis l'URL (?section=...)
            const sectionParam = new URLSearchParams(window.location.search).get('section');
            if (sectionParam) {
                if (sectionParam === 'formationNav') {
                    document.getElementById('formationNav').scrollIntoView({ behavior: 'smooth' });
                } else {
                    const targetButton = document.querySelector(`.formation-nav-btn[data-target="${sectionParam}"]`);
                    if (targetButton) {
                        targetButton.click();
                    }

                    const targetSection = document.getElementById(sectionParam);
                    if (targetSection) {
                        targetSection.scrollIntoView({ behavior: 'smooth' });
                    }
                }
            }
            
            // Fonction pour afficher les messages
            function showMessage(text, type = 'info') {
                const message = document.createElement('div');
                message.className = `user-message user-message-${type}`;
                message.innerHTML = `
                    <i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'}"></i>
                    <div>
                        <strong>${type === 'success' ? 'Succès' : 'Information'}</strong>
                        <p>${text}</p>
                    </div>
                `;
                
                document.body.appendChild(message);
                
                setTimeout(() => {
                    message.classList.add('show');
                }, 10);
                
                setTimeout(() => {
                    message.classList.remove('show');
                    setTimeout(() => message.remove(), 300);
                }, 5000);
            }
            
            // Gestion du menu mobile
            const mobileMenuBtn = document.getElementById('mobileMenuBtn');
            const mainNav = document.getElementById('mainNav');
            
            if (mobileMenuBtn) {
                mobileMenuBtn.addEventListener('click', () => {
                    mainNav.classList.toggle('show');
                    mobileMenuBtn.innerHTML = mainNav.classList.contains('show') 
                        ? '<i class="fas fa-times"></i>' 
                        : '<i class="fas fa-bars"></i>';
                });
            }
            
            // Fermer le menu mobile en cliquant sur un lien
            document.querySelectorAll('nav a').forEach(link => {
                link.addEventListener('click', () => {
                    if (mainNav && mainNav.classList.contains('show')) {
                        mainNav.classList.remove('show');
                        mobileMenuBtn.innerHTML = '<i class="fas fa-bars"></i>';
                    }
                });
            });
            
            // Initialisation
            console.log('Page formations dynamique initialisée !');
        });
    </script>
